(N'How do I submit a Grade Appeal?', N'Navigate to the Grade Appeals section in the portal, select the course grade you wish to appeal, fill out the appeal reason, attach supporting documents, and click Submit.', N'Academic Policies', N'appeal,grade,academic', SYSUTCDATETIME(), 1),
(N'What are the course registration deadlines for HKIII 2025-2026?', N'Course registration for HKIII 2025-2026 opens on June 1, 2026 and closes on June 15, 2026. Late registrations incur a administrative fee.', N'Course Registration', N'registration,deadline,hk3', SYSUTCDATETIME(), 1),
(N'How is Cumulative GPA calculated?', N'GPA is calculated by multiplying each course grade point by its credit weight, summing these products, and dividing by total credits earned.', N'Grading & GPA', N'gpa,grading,credits', SYSUTCDATETIME(), 1),
(N'What payment methods are supported for tuition fees?', N'Tuition fees can be paid via Online Bank Transfer, VNPay Gateway, or direct cash payment at the Academic Financial Office.', N'Tuition & Finance', N'tuition,payment,finance', SYSUTCDATETIME(), 1),
(N'How does the AI Learning Path Chatbot work?', N'The AI Chatbot analyzes your transcript, prerequisite requirements, and major curriculum to recommend optimal course roadmaps and elective choices.', N'AI Counseling', N'chatbot,ai,advising', SYSUTCDATETIME(), 1);

